cypress_script:
describe('Dropdown Selection Test', () => {
  it('should select an option from the dropdown and display it', () => {
    cy.visit('https://the-internet.herokuapp.com/dropdown');
    cy.get('#dropdown').select('1');
    cy.get('#dropdown').should('have.value', '1');
  });
  it('should remain unselected when the default option is selected', () => {
    cy.visit('https://the-internet.herokuapp.com/dropdown');
    cy.get('#dropdown').select('');
    cy.get('#dropdown').should('have.value', '');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Dropdown Selection Test', () => {
  test('should select an option from the dropdown and display it', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dropdown');
    await page.selectOption('#dropdown', '1');
    const selectedValue = await page.locator('#dropdown').inputValue();
    expect(selectedValue).toBe('1');
  });
  test('should remain unselected when the default option is selected', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dropdown');
    await page.selectOption('#dropdown', '');
    const selectedValue = await page.locator('#dropdown').inputValue();
    expect(selectedValue).toBe('');
  });
});
